// Uma linha da planilha por INSCRITO -- de QUALQUER live.
//
// Este workflow e' o PADRAO: a MESMA URL de webhook serve todas as LPs de live
// (/, /peru, /costa-amalfitana, /tailandia, /turquia, /islandia, /egito). O que
// separa uma live da outra e' a coluna "Destino" (o campo `slug` do payload) --
// e e' por ela que a linha tambem vai para a ABA daquela live.
//
// ⚠️ Nomes das chaves = nomes das COLUNAS. O no do Sheets mapeia por NOME, e
// coluna que nao existe no cabecalho da linha 1 e' DESCARTADA EM SILENCIO --
// nao da erro, o dado simplesmente some. Cabecalho exato esperado:
//
//   Data/hora | Destino | Nome | WhatsApp | E-mail | Expedicao | Live |
//   Data da live | Formulario | Origem | utm_source | utm_medium |
//   utm_campaign | utm_content | utm_term | utm_id | gclid | fbclid |
//   gbraid | wbraid | Fonte | source_id | lead_id
//
// A chave `_aba` NAO e' coluna: e' o nome da aba, lido pelo no seguinte. Como
// nao existe no cabecalho, o Sheets a descarta sozinho.

// ============================================================================
//  A ABA DE CADA LIVE
// ============================================================================
//  A chave e' o `slug` que a LP manda (a mesma coisa da coluna Destino).
//  O valor e' o NOME EXATO da aba na planilha -- se nao bater, a linha nao vai
//  para a aba da live (mas NAO se perde: ela ja foi gravada na aba geral pelo
//  no anterior).
//
//  Live nova = uma linha aqui + criar a aba com o mesmo cabecalho.
// ============================================================================
const ABA_POR_DESTINO = {
  'japao-live':            'Japao 20-09',
  'peru-live':             'Peru 03-09',
  'costa-amalfitana-live': 'Amalfitana 08-09',
  'tailandia-live':        'Tailandia 13-09',
  'turquia-live':          'Turquia 15-09',
  'islandia-live':         'Islandia 17-09',
  'egito-live':            'Egito 29-09',
};

const txt = (v) => String(v ?? '').trim();

// Telefone como TEXTO: sem o apostrofo o Sheets come o '+' e transforma
// +5511987654321 em notacao cientifica -- e telefone quebrado nao dispara no
// ManyChat.
const comoTexto = (v) => (txt(v) ? "'" + txt(v) : '');

// '2026-09-29T20:00:00-03:00' -> '29/09/2026 20:00' (fuso de Brasilia)
function dataBR(iso) {
  const s = txt(iso);
  if (!s) return '';
  const d = new Date(s);
  if (isNaN(d.getTime())) return s;
  try {
    return new Intl.DateTimeFormat('pt-BR', {
      day: '2-digit', month: '2-digit', year: 'numeric',
      hour: '2-digit', minute: '2-digit',
      timeZone: 'America/Sao_Paulo',
    }).format(d).replace(', ', ' ');
  } catch (e) { return s; }
}

const linhas = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const destino = txt(b.slug) || 'desconhecido';

  // Origem legivel de bater o olho: "google / cpc / live-egito".
  const origem = [b.utm_source, b.utm_medium, b.utm_campaign, b.utm_content]
    .filter(Boolean)
    .join(' / ');

  linhas.push({
    json: {
      'Data/hora': txt(b.data_hora_cadastro),
      // ⚠️ E' por esta coluna que voce FILTRA antes de disparar no ManyChat --
      // e e' ela que escolhe a aba, logo abaixo. Sem isso, quem se inscreveu
      // na live do Egito recebe o aviso da live do Japao.
      'Destino': destino,
      'Nome': txt(b.nome),
      // Cada live escolhe os campos que pede (live.formulario nas LPs). Hoje
      // TODAS pedem nome + WhatsApp: a coluna E-mail vem vazia, e isso e'
      // esperado, nao e' falha de captura. Se uma live voltar a pedir e-mail,
      // o dado cai nesta coluna sem mexer aqui.
      'WhatsApp': comoTexto(b.whatsapp),
      'E-mail': txt(b.email).toLowerCase(),
      'Expedicao': txt(b.expedicao),
      'Live': txt(b.evento_titulo),
      'Data da live': dataBR(b.evento_inicio),
      'Formulario': b.posicao === 'fim' ? 'fim da pagina' : 'topo da pagina',
      'Origem': origem,
      'utm_source': txt(b.utm_source),
      'utm_medium': txt(b.utm_medium),
      'utm_campaign': txt(b.utm_campaign),
      'utm_content': txt(b.utm_content),
      'utm_term': txt(b.utm_term),
      'utm_id': txt(b.utm_id),
      'gclid': txt(b.gclid),
      'fbclid': txt(b.fbclid),
      'gbraid': txt(b.gbraid),
      'wbraid': txt(b.wbraid),
      // Como o lead nasce no Bitrix -- serve para cruzar planilha x CRM.
      'Fonte': txt(b.fonte),
      'source_id': txt(b.source_id),
      'lead_id': txt(b.lead_id),

      // controle, nao e' coluna:
      '_aba': ABA_POR_DESTINO[destino] || '',
    },
  });
}

return linhas;

// Uma linha da planilha por pessoa que ENTROU na sala -- de QUALQUER live.
//
// O payload vem de /api/entrar-live, e a pagina /entrar manda o `slug` da live
// pelo `?live=` da URL. Mesma ideia do de cima: uma URL so' para todas as
// lives, separadas pela coluna "Destino" e por uma aba propria.
//
