      'Origem': origem,
      'utm_source': txt(b.utm_source),
      'utm_medium': txt(b.utm_medium),
      'utm_campaign': txt(b.utm_campaign),
      'utm_content': txt(b.utm_content),
      'utm_term': txt(b.utm_term),
      'utm_id': txt(b.utm_id),
      'gclid': txt(b.gclid),
      'fbclid': txt(b.fbclid),
      'gbraid': txt(b.gbraid),
      'wbraid': txt(b.wbraid),
      'lead_id': txt(b.lead_id),

